export const errorCatalogueSource = "{\n  \"schemaVersion\": 1,\n  \"helpPath\": \"/help/\",\n  \"retry\": {\n    \"same\": {\"first\": \"\", \"then\": \"Send the same request again unchanged, with the same request ID or payment authorization: the server never does one request twice.\", \"owner\": \"The agent sends the same request again.\"},\n    \"owner\": {\"first\": \"\", \"then\": \"Wait until the owner has acted on it. Then send the same request again unchanged, with the same request ID.\", \"owner\": \"The agent sends the same request again once you have acted on it.\"},\n    \"final\": {\"first\": \"Read the earlier request with allowit status ID first.\", \"then\": \"If it is pending, wait. If it is the same purchase and it settled, do not pay for it again. Send a new request with a new request ID only once the earlier one is denied, expired or failed, or when it was another purchase.\", \"owner\": \"The agent reads the earlier request first and does not pay twice for one purchase.\"},\n    \"settled\": {\"first\": \"\", \"then\": \"Do not pay for this purchase again. Read the earlier request with allowit status ID until it is final, or ask the seller for the result.\", \"owner\": \"The agent does not pay for this purchase again.\"},\n    \"none\": {\"first\": \"\", \"then\": \"Do not send this request again. Ask the owner before a new request for the same purchase.\", \"owner\": \"The agent does not send it again without you.\"}\n  },\n  \"entries\": [\n    {\"code\": \"session_ended\", \"for\": \"owner\", \"title\": \"The session ended\", \"cause\": \"The sign-in is no longer valid on this server. The policies and drafts are saved.\", \"next\": \"Sign in with your wallet again.\"},\n    {\"code\": \"sign_in_expired\", \"for\": \"owner\", \"title\": \"The sign-in message expired\", \"cause\": \"Each sign-in message works once and for a short time. This one was used, changed or too old.\", \"next\": \"Start the sign-in again and approve the new message in your wallet.\"},\n    {\"code\": \"sign_in_signature_invalid\", \"for\": \"owner\", \"title\": \"The wallet signature did not match\", \"cause\": \"The signature that the wallet returned does not belong to the account and the message of this sign-in.\", \"next\": \"Select the account that you want to use in your wallet, then sign in again.\"},\n    {\"code\": \"app_origin_required\", \"for\": \"agent\", \"title\": \"The request did not come from the Allowit app\", \"cause\": \"This server takes owner requests only from the pages of its own app. A page of another address, or an allowit CLI of another release, sent this one.\", \"next\": \"Open Allowit at the address of this server's app, sign in there and do the step again. The agent sends the same request again.\", \"agent\": \"Install the allowit CLI with the install line of this server's app. Send the same request again unchanged, with the same request ID or payment authorization: the server never does one request twice.\", \"retry\": \"same\"},\n    {\"code\": \"rate_limited\", \"for\": \"owner\", \"title\": \"Too many requests at once\", \"cause\": \"Allowit limits how often this step runs.\", \"next\": \"Wait a minute, then do the step again.\"},\n    {\"code\": \"service_not_configured\", \"for\": \"operator\", \"title\": \"This server does not offer this function\", \"cause\": \"The server has no configuration for the function that this step needs.\", \"next\": \"Use another network or another Allowit server. The operator of this server can turn the function on.\"},\n    {\"code\": \"storage_unavailable\", \"for\": \"owner\", \"title\": \"The server's storage did not answer\", \"cause\": \"The server could not read or write its storage for this step. A step that reached the network before can still have taken effect.\", \"next\": \"Wait a moment and reload the page. If a step was under way, check in History whether it took effect before you do it again.\"},\n    {\"code\": \"service_unreachable\", \"for\": \"owner\", \"title\": \"Allowit did not answer\", \"cause\": \"The Allowit server could not be reached, or its answer was unreadable. The step may have reached the server before the connection failed.\", \"next\": \"Check your connection and reload the page. Read the policy's state before you do the step again.\", \"agent\": \"Check ALLOWIT_URL and the connection. Send the same request again unchanged, with the same request ID or payment authorization: the server never does one request twice.\", \"retry\": \"same\"},\n    {\"code\": \"server_release_differs\", \"for\": \"agent\", \"title\": \"The CLI and the server are different releases\", \"cause\": \"The server does not know the request of this allowit CLI. The server is an earlier or a later release than the CLI, or ALLOWIT_URL names another site.\", \"next\": \"Give the agent the agent prompt from Agent access again: its install line installs the CLI that this server serves. The agent sends the same request again.\", \"agent\": \"Check ALLOWIT_URL. Then install the CLI that this server serves with the install line of its app. Send the same request again unchanged, with the same request ID or payment authorization: the server never does one request twice.\", \"retry\": \"same\"},\n    {\"code\": \"method_not_allowed\", \"for\": \"agent\", \"title\": \"The server does not take this request here\", \"cause\": \"The route exists and takes another kind of request, which the details name when the server knows the route.\", \"next\": \"No action is needed. A tool of the agent that sent it uses the request method that the route documents.\", \"agent\": \"Use the request method that the details or the documentation of the route name.\"},\n    {\"code\": \"wallet_unavailable\", \"for\": \"owner\", \"title\": \"The wallet did not connect\", \"cause\": \"The app found no wallet extension that it can use, or the wallet refused the connection.\", \"next\": \"Install or unlock your wallet extension, allow this site, and choose the network that the app shows. Then sign in again.\"},\n    {\"code\": \"wallet_signing_failed\", \"for\": \"owner\", \"title\": \"The wallet did not sign\", \"cause\": \"The wallet returned an error in place of a signature.\", \"next\": \"Open your wallet, check that the owner account and the network are selected, and sign the step again.\"},\n    {\"code\": \"signing_cancelled\", \"for\": \"owner\", \"title\": \"The signature was cancelled\", \"cause\": \"The wallet closed without a signature for this step.\", \"next\": \"Start the step again when you want to sign.\"},\n    {\"code\": \"wallet_wrong_account\", \"for\": \"owner\", \"title\": \"The signature does not fit the owner account\", \"cause\": \"The wallet returned a signature that does not verify for the owner account and this step: another account signed, or the wallet signed an earlier message.\", \"next\": \"Select the owner account in your wallet and sign this step again.\"},\n    {\"code\": \"wallet_signed_other_transaction\", \"for\": \"owner\", \"title\": \"The wallet signed another transaction\", \"cause\": \"The wallet returned a signature of another transaction than the step that the page shows.\", \"next\": \"Do the step again, and sign only the step that the page shows. If the wallet changes the step again, use another wallet extension.\"},\n    {\"code\": \"owner_wrong_network\", \"for\": \"owner\", \"title\": \"The owner account is on another network\", \"cause\": \"The sign-in is on another network than the one that this policy uses.\", \"next\": \"Choose the policy's network in the header, sign in with your owner account there, and open Review and sign again.\"},\n    {\"code\": \"owner_account_unfunded\", \"for\": \"owner\", \"title\": \"The owner account has no funds yet\", \"cause\": \"The network holds no account for the owner address. An account exists from the moment it receives its first funds.\", \"next\": \"Send funds to your owner address. On a test network, use the faucet of that network. Then open Review and sign again.\"},\n    {\"code\": \"owner_balance_low\", \"for\": \"owner\", \"title\": \"The owner account holds too little\", \"cause\": \"The owner account pays the funding of the wallet, the reserve that the network keeps and the fee of the setup, in one asset or two. It holds less than these need.\", \"next\": \"Add the asset that the details name as short to your owner account. Lower the funding amount in the conversation only when the funding asset is short. Then sign again.\"},\n    {\"code\": \"account_not_found\", \"for\": \"owner\", \"title\": \"The network holds no account for this address\", \"cause\": \"An account exists from the moment it receives its first funds, and the network holds none for an account that this step reads.\", \"next\": \"Check in your wallet that the owner account holds funds on this network, then do the step again. If it does, give the operator of this server the code account_not_found.\"},\n    {\"code\": \"owner_step_open\", \"for\": \"owner\", \"title\": \"Another step waits for the owner's signature\", \"cause\": \"One owner step runs at a time for an account, in this tab and in every other tab.\", \"next\": \"Finish or cancel the open step, then start this one.\"},\n    {\"code\": \"signer_unavailable\", \"for\": \"owner\", \"title\": \"The app cannot sign on this network\", \"cause\": \"The app holds no wallet connection that signs owner steps on this network.\", \"next\": \"Choose a network from the header's list and sign in there.\"},\n    {\"code\": \"rail_element_unavailable\", \"for\": \"owner\", \"title\": \"The app cannot show this step on this network\", \"cause\": \"The rail of this network has no part of the app for this step, or the page names a network that the app does not know.\", \"next\": \"Choose a network from the header's list and do the step there.\"},\n    {\"code\": \"model_busy\", \"for\": \"owner\", \"title\": \"The drafting model is busy\", \"cause\": \"Nothing was lost. No model wrote the draft this time, and the words stay in the form.\", \"next\": \"Choose Try again, or Revise for a change of a draft. Allowit sends the same request and creates at most one draft.\"},\n    {\"code\": \"model_timeout\", \"for\": \"owner\", \"title\": \"The model took too long\", \"cause\": \"The model did not answer within its time limit.\", \"next\": \"Send the same request again.\"},\n    {\"code\": \"model_unreachable\", \"for\": \"owner\", \"title\": \"The model could not be reached\", \"cause\": \"Allowit could not connect to the model that this step uses.\", \"next\": \"Send the same request again in a moment.\"},\n    {\"code\": \"build_gate_unavailable\", \"for\": \"owner\", \"title\": \"The policy check did not run\", \"cause\": \"Allowit builds each draft to check it, and that check was unavailable.\", \"next\": \"Send the same request again in a moment.\"},\n    {\"code\": \"build_gate\", \"for\": \"owner\", \"title\": \"The draft did not pass the policy check\", \"cause\": \"Allowit wrote a policy from the request several times, and its check refused each one.\", \"next\": \"Say what the agent may do in plain terms: the amounts, the recipients and a time limit. Then send it again.\"},\n    {\"code\": \"recognizer_mismatch\", \"for\": \"operator\", \"title\": \"Allowit could not classify the draft\", \"cause\": \"Two checks of the policy source disagree. This is a fault of the server, not of the policy.\", \"next\": \"Send the request again. If it repeats, give the operator of this server the code recognizer_mismatch.\"},\n    {\"code\": \"wallet_kind_unknown\", \"for\": \"owner\", \"title\": \"Choose a wallet kind\", \"cause\": \"The step names no wallet kind, or a kind that Allowit does not know.\", \"next\": \"Choose Native, Simple, Standard or Custom in the wallet kind list. Then do the step again.\"},\n    {\"code\": \"wallet_kind_unsupported\", \"for\": \"owner\", \"title\": \"This wallet kind cannot serve the policy\", \"cause\": \"The chosen wallet kind cannot enforce this policy on this network. The details state the reason.\", \"next\": \"Read the reason in the details, then choose a wallet kind in the list that can enforce this policy on this network.\"},\n    {\"code\": \"custom_policy_needs_custom_wallet\", \"for\": \"owner\", \"title\": \"This policy needs a Custom wallet\", \"cause\": \"The policy holds custom conditions that only a Custom wallet compiles.\", \"next\": \"Choose the Custom wallet kind and send the request again.\"},\n    {\"code\": \"server_policy_needs_server_custody\", \"for\": \"owner\", \"title\": \"A Custom wallet cannot hold this policy\", \"cause\": \"A part of the policy looks something up or asks a question, which only the server can run. This server deploys a Custom wallet only for a policy that it compiles whole on chain.\", \"next\": \"Choose Standard when its canonical rules cover the policy's on-chain conditions, or Native, whose rules the server checks off chain before it co-signs. Either kind runs the lookup on the server.\"},\n    {\"code\": \"host_value_needs_source\", \"for\": \"owner\", \"title\": \"The wallet cannot store one of the values\", \"cause\": \"The part of the policy that the server runs reads a value that a contract wallet does not keep.\", \"next\": \"Choose the Native wallet kind, or state that value as a fixed number in your request.\"},\n    {\"code\": \"agent_public_key_invalid\", \"for\": \"owner\", \"title\": \"The agent public key is not valid here\", \"cause\": \"The key in the message is not an account address on this network.\", \"next\": \"Copy the public key that the agent printed, whole, and send it again.\"},\n    {\"code\": \"wallet_agent_differs\", \"for\": \"owner\", \"title\": \"This wallet serves another agent key\", \"cause\": \"The wallet of this draft is set up for another agent public key than the message names.\", \"next\": \"Name the agent key that the wallet serves, or set up a new wallet for the new key.\"},\n    {\"code\": \"funding_amount_invalid\", \"for\": \"owner\", \"title\": \"The funding amount is not a plain number\", \"cause\": \"Allowit reads the funding amount as a positive decimal number, such as 10 or 2.5, with no more decimal places than its asset has.\", \"next\": \"State the amount again in the conversation as a plain positive number, with no more decimal places than its asset has.\"},\n    {\"code\": \"wallet_creation_prepared\", \"for\": \"owner\", \"title\": \"This draft is fixed\", \"cause\": \"A wallet creation was prepared for this draft, so its values can no longer change.\", \"next\": \"Sign it in Review and sign, or start a new policy for other values.\"},\n    {\"code\": \"time_passed\", \"for\": \"owner\", \"title\": \"The time limit is in the past\", \"cause\": \"The policy ends at a time that has already passed.\", \"next\": \"State a new time limit in the conversation, or change the Expires value in the policy code.\"},\n    {\"code\": \"asset_mismatch\", \"for\": \"owner\", \"title\": \"The request names another asset\", \"cause\": \"The policy counts in one asset and the request or its wallet uses another.\", \"next\": \"Name the asset of the policy's wallet, or start a new policy for the other asset.\"},\n    {\"code\": \"param_invalid\", \"for\": \"owner\", \"title\": \"A value has the wrong form\", \"cause\": \"One of the values is not what its rule expects, such as text where a number belongs, or a change names no value or more than 32.\", \"next\": \"Open the value in the policy code and enter it again in the form that its editor shows. Change from 1 to 32 values at once.\"},\n    {\"code\": \"param_out_of_range\", \"for\": \"owner\", \"title\": \"A value is out of range\", \"cause\": \"One of the values is smaller or larger than its rule allows.\", \"next\": \"Open the value in the policy code and enter a value inside the range in the details.\"},\n    {\"code\": \"workspace_full\", \"for\": \"owner\", \"title\": \"The workspace is full\", \"cause\": \"An account keeps up to 30 policies on this server, and a stopped policy still counts.\", \"next\": \"Use another owner account for the new policy, or ask the operator of this server for room.\"},\n    {\"code\": \"workspace_too_large\", \"for\": \"owner\", \"title\": \"The saved policies are too large\", \"cause\": \"The saved policies of an account have a size limit, and this change would pass it.\", \"next\": \"Ask the operator of this server for room.\"},\n    {\"code\": \"prompt_length\", \"for\": \"owner\", \"title\": \"The request is too short or too long\", \"cause\": \"Allowit drafts a policy from a request of 5 to 3,000 characters.\", \"next\": \"Say what the agent may do in a few sentences and send it again.\"},\n    {\"code\": \"conversation_full\", \"for\": \"owner\", \"title\": \"This conversation is full\", \"cause\": \"A draft keeps a limited number of revisions.\", \"next\": \"Start a new policy and state the complete rules in its first message.\"},\n    {\"code\": \"policy_not_found\", \"for\": \"owner\", \"title\": \"This policy is not in the workspace\", \"cause\": \"The signed-in account has no policy with this id. It was removed, or it belongs to another account or network.\", \"next\": \"Open the policy list, check the network and the account in the header, and choose the policy again.\"},\n    {\"code\": \"policy_revision_changed\", \"for\": \"owner\", \"title\": \"The draft changed in the meantime\", \"cause\": \"The change was made for an earlier revision of this draft, or another draft was created at the same moment.\", \"next\": \"Reload the page and read the current state. Then make the change, or create the draft, again.\"},\n    {\"code\": \"draft_signed\", \"for\": \"owner\", \"title\": \"A signed policy is not revised\", \"cause\": \"This policy is signed and its wallet exists. Its source no longer changes.\", \"next\": \"Change a value in the policy code with one signature, or start a new policy for other rules.\"},\n    {\"code\": \"review_values_missing\", \"for\": \"owner\", \"title\": \"The agent key or the funding amount is missing\", \"cause\": \"Review and sign needs the public key of the agent and the amount that funds the wallet. The conversation has not collected both.\", \"next\": \"Give your agent the agent setup line. Then state its public key and the funding amount in the conversation.\"},\n    {\"code\": \"agent_key_is_owner\", \"for\": \"owner\", \"title\": \"The agent key is not a key of its own\", \"cause\": \"The agent public key equals the owner account or the key of the server. The agent must hold a key of its own.\", \"next\": \"Give your agent the agent setup line, and state the public key that it prints in the conversation.\"},\n    {\"code\": \"draft_changed\", \"for\": \"owner\", \"title\": \"The draft changed after it was opened\", \"cause\": \"Review and sign shows one exact revision, and the saved draft is at another one now.\", \"next\": \"Close the review, read the current revision, and open Review and sign again.\"},\n    {\"code\": \"review_busy\", \"for\": \"owner\", \"title\": \"This review is being signed elsewhere\", \"cause\": \"The same review runs in this tab or in another tab of this browser.\", \"next\": \"Finish it there, or close the other tab and open Review and sign again.\"},\n    {\"code\": \"review_link_invalid\", \"for\": \"owner\", \"title\": \"The review link is incomplete\", \"cause\": \"The link from the chat does not hold a complete policy proposal.\", \"next\": \"Return to the chat and open its Review and sign link again.\"},\n    {\"code\": \"review_differs\", \"for\": \"owner\", \"title\": \"The step to sign differs from the one shown\", \"cause\": \"What would be signed is not the policy, the values, the wallet kind or the step that this page shows.\", \"next\": \"Do not sign it. Reload the page, open the policy from the list and do the step again from there.\"},\n    {\"code\": \"draft_running\", \"for\": \"owner\", \"title\": \"Allowit is still busy with a draft\", \"cause\": \"A conversation writes one draft at a time, and new drafts are limited to a few each minute. The last draft is unchanged.\", \"next\": \"Wait a minute, then send your message again.\"},\n    {\"code\": \"agent_capacity\", \"for\": \"owner\", \"title\": \"The agent takes no more conversations now\", \"cause\": \"This agent keeps a limited number of open conversations and drafts.\", \"next\": \"Try again in a few minutes.\"},\n    {\"code\": \"conversation_ended\", \"for\": \"owner\", \"title\": \"This conversation ended\", \"cause\": \"The agent no longer holds this conversation. A policy that was opened in Allowit is saved there.\", \"next\": \"Start a new conversation and say again what the agent may do.\"},\n    {\"code\": \"wallet_not_set_up\", \"for\": \"owner\", \"title\": \"The agent's wallet account does not exist yet\", \"cause\": \"A Native policy pays from an account that the owner's signature creates for the agent, and this draft names one that was never set up.\", \"next\": \"Start the policy from New policy with the Native kind: Review and sign creates and funds the account with one signature.\"},\n    {\"code\": \"wallet_choice_needed\", \"for\": \"owner\", \"title\": \"Several wallet accounts match\", \"cause\": \"The owner account has more than one Native wallet account on this network, and the step names none of them.\", \"next\": \"Name one of the wallet accounts that the details list in the conversation, then do the step again.\"},\n    {\"code\": \"wallet_setup_required\", \"for\": \"owner\", \"title\": \"Set up the wallet account first\", \"cause\": \"The policy's wallet is a new account for the agent. It exists once the owner signs its setup.\", \"next\": \"Open Review and sign and choose Sign and fund. The first signature creates and funds the account.\"},\n    {\"code\": \"wallet_not_deployed\", \"for\": \"owner\", \"title\": \"The wallet is not deployed yet\", \"cause\": \"The policy has no wallet on the network, so it cannot be approved or run.\", \"next\": \"Open Review and sign and finish the deployment.\"},\n    {\"code\": \"draft_not_bindable\", \"for\": \"owner\", \"title\": \"This wallet account cannot hold the draft\", \"cause\": \"The account that was set up does not match the draft. The details state what differs.\", \"next\": \"Start a new policy and sign its setup again.\"},\n    {\"code\": \"wallet_already_registered\", \"for\": \"owner\", \"title\": \"This wallet belongs to another policy\", \"cause\": \"The wallet account is registered for another policy, with another owner, or with another agent key.\", \"next\": \"Start a new policy. Review and sign creates a new wallet account for it.\"},\n    {\"code\": \"installation_unverified\", \"for\": \"owner\", \"title\": \"The wallet exists, and Allowit has not confirmed it yet\", \"cause\": \"The network confirmed the creation of the wallet. Allowit then read the wallet from the ledger, and that read failed or showed other values.\", \"next\": \"Choose Resume in Review and sign. It reads the wallet again and signs nothing twice.\"},\n    {\"code\": \"template_changed\", \"for\": \"owner\", \"title\": \"The network's wallet settings changed\", \"cause\": \"The asset or the fee ceiling of this network's wallets changed after this draft was made.\", \"next\": \"Start a new policy with the same words. The new draft uses the current settings.\"},\n    {\"code\": \"owner_transaction_expired\", \"for\": \"owner\", \"title\": \"The signature came too late\", \"cause\": \"A prepared step or an owner approval is valid for a few minutes, and this one passed its time limit. Whether a signed transaction applied before then is not known yet.\", \"next\": \"Do the same step again, or choose Resume in Review and sign. Allowit checks the saved step first, and asks for a new signature only when the saved step never applied.\"},\n    {\"code\": \"owner_transaction_unconfirmed\", \"for\": \"owner\", \"title\": \"The network has not shown the signed step yet\", \"cause\": \"The signed step passed its time limit, and the network could not be read to tell whether it applied.\", \"next\": \"Wait a moment, then choose Resume in Review and sign: Allowit reads the network again before it asks for a new signature.\"},\n    {\"code\": \"owner_transaction_pending\", \"for\": \"owner\", \"title\": \"The network has not confirmed the step yet\", \"cause\": \"The signed step was sent, and its result is not known yet.\", \"next\": \"Wait a moment, then do the same step again. Allowit sends the saved step as it is; you sign a new step only when the saved one can no longer apply.\"},\n    {\"code\": \"owner_transactions_unresolved\", \"for\": \"owner\", \"title\": \"Earlier steps still wait for their results\", \"cause\": \"This owner account has as many sent steps as Allowit keeps, and each of them waits for its result on the network.\", \"next\": \"Choose Resume in Review and sign, or do each earlier step again where it started: Allowit reads the result of a sent step before it prepares a new one. Then do this step.\"},\n    {\"code\": \"owner_transaction_settled\", \"for\": \"owner\", \"title\": \"An earlier step already applied\", \"cause\": \"A step that the owner signed before this one is on the ledger. Allowit reads its result before it prepares a new step.\", \"next\": \"Reload the page or open History to see the applied step, then do the next step from there.\"},\n    {\"code\": \"owner_transaction_failed\", \"for\": \"owner\", \"title\": \"The network refused the step\", \"cause\": \"The transaction that the owner signed reached the network and failed there. The most frequent cause is an owner account that holds too little for the amount, the reserve and the fee.\", \"next\": \"Check the balance of your owner account and add funds if it is low. Then do the same step again: it asks for a new signature.\"},\n    {\"code\": \"owner_result_unavailable\", \"for\": \"owner\", \"title\": \"The result of an earlier step is no longer readable\", \"cause\": \"The step applied some time ago, and the network's recent history no longer holds its result.\", \"next\": \"Open History and the wallet's explorer link to see what applied. Then continue from the policy page.\"},\n    {\"code\": \"stale_owner_observation\", \"for\": \"owner\", \"title\": \"The wallet changed while the step was prepared\", \"cause\": \"Allowit read the wallet, and the ledger changed it before the step was ready.\", \"next\": \"Do the step again. Allowit reads the current state.\"},\n    {\"code\": \"network_unavailable\", \"for\": \"owner\", \"title\": \"The network did not answer\", \"cause\": \"Allowit got no answer in time from the payment network or the server, and the step may have reached them.\", \"next\": \"Wait a moment and reload the page. If the step shows as pending, choose Resume. Start it again only when the page shows that it did not apply.\", \"agent\": \"Wait a moment, and check the connection. Send the same request again unchanged, with the same request ID or payment authorization: the server never does one request twice.\", \"retry\": \"same\"},\n    {\"code\": \"operation_expired\", \"for\": \"agent\", \"title\": \"The prepared payment expired\", \"cause\": \"A prepared operation is valid for a short time, and this one passed it before it was submitted. The status of the request shows the outcome of an earlier submission.\", \"next\": \"No action is needed. The agent reads the earlier request first and does not pay twice for one purchase.\", \"agent\": \"Read the earlier request with allowit status ID first. If it is pending, wait. If it is the same purchase and it settled, do not pay for it again. Send a new request with a new request ID only once the earlier one is denied, expired or failed, or when it was another purchase.\", \"retry\": \"final\"},\n    {\"code\": \"params_differ_from_wallet\", \"for\": \"owner\", \"title\": \"The wallet enforces other values\", \"cause\": \"The values that the policy shows differ from the values that its wallet holds on the ledger.\", \"next\": \"Compare the policy's values with History. The wallet keeps its own values: start a new policy for the values that you want.\", \"agent\": \"Do not rely on the limits that it shows. Tell the owner that the wallet's values and the policy's values differ.\"},\n    {\"code\": \"rail_journal_unreadable\", \"for\": \"operator\", \"title\": \"The server's wallet journal is unreadable\", \"cause\": \"The journal of this wallet on the server uses a retired format. The operator keeps it, as it records earlier operations, and resolves the wallet's pending operations.\", \"next\": \"Tell the operator of this server the wallet and this code, and do not repeat the step until the operator has resolved the wallet.\"},\n    {\"code\": \"custom_policy_unknown\", \"for\": \"owner\", \"title\": \"No Custom policy waits for this build\", \"cause\": \"The server holds no Custom policy with this id and build ticket.\", \"next\": \"Copy the build command from Review and sign again and run it.\"},\n    {\"code\": \"custom_code_hash_mismatch\", \"for\": \"owner\", \"title\": \"The built code differs\", \"cause\": \"The wallet code on the server or on the ledger is not the code that this client built from the policy source.\", \"next\": \"Do not sign. Run the build command from Review and sign again, and sign only when the hashes match.\"},\n    {\"code\": \"wallet_code_differs\", \"for\": \"owner\", \"title\": \"The wallet runs other code than its build\", \"cause\": \"The code of the wallet on the ledger differs from the code of its configuration.\", \"next\": \"Stop using this wallet, and give the operator of this server the code wallet_code_differs.\"},\n    {\"code\": \"custom_toolchain_missing\", \"for\": \"owner\", \"title\": \"A build tool is missing\", \"cause\": \"The build of a Custom wallet needs build tools on this machine. The details name the tool that is missing or has another version.\", \"next\": \"Install the tool that the details name, then run the build command again.\"},\n    {\"code\": \"custom_build_failed\", \"for\": \"owner\", \"title\": \"The wallet code did not build\", \"cause\": \"The build tools ran on this device and failed, such as for a dependency that could not be fetched or a tool that stopped. The details hold the build output.\", \"next\": \"Fix the local problem that the details name, then run the build command from Review and sign again.\"},\n    {\"code\": \"custom_source_rejected\", \"for\": \"owner\", \"title\": \"The policy source does not pass the build check\", \"cause\": \"The build compiles only a policy source that passes its source gate, and this source does not. The details name the reason.\", \"next\": \"Revise the policy in the conversation of its draft, then run the build command again.\"},\n    {\"code\": \"custom_build_missing\", \"for\": \"owner\", \"title\": \"This Custom policy has no build yet\", \"cause\": \"A Custom wallet runs code that is built from the policy source and attested by the owner. The server has no attested build for this policy.\", \"next\": \"Run the build command from Review and sign in a terminal with the allowit CLI, then sign the attestation of the build in Review and sign.\"},\n    {\"code\": \"custom_policy_changed\", \"for\": \"owner\", \"title\": \"The policy changed during the build\", \"cause\": \"The source of the policy is not the source that the build command named.\", \"next\": \"Copy the build command from Review and sign again and build that source.\"},\n    {\"code\": \"custom_build_attested\", \"for\": \"owner\", \"title\": \"The build is already attested\", \"cause\": \"The owner attested a build of this policy, and an attested build does not change.\", \"next\": \"Deploy that build, or revise the policy and build it again.\"},\n    {\"code\": \"custom_presignature_mismatch\", \"for\": \"owner\", \"title\": \"The attestation belongs to another build\", \"cause\": \"The attestation names another build ticket than the one of this policy's source.\", \"next\": \"Run the build command again and sign the attestation of that build.\"},\n    {\"code\": \"custom_attestation_invalid\", \"for\": \"owner\", \"title\": \"The build attestation is not valid\", \"cause\": \"The signature of the attestation is not the owner account's signature for this build.\", \"next\": \"Run the build command again and sign the attestation with your owner account.\"},\n    {\"code\": \"update_unavailable\", \"for\": \"owner\", \"title\": \"This policy takes no signed value change\", \"cause\": \"Only an active policy changes a value with a signature, and only a value that its wallet takes: a Native wallet takes it with a new approval, a contract wallet only for a value that it stores.\", \"next\": \"Change a draft's value in its policy code. For a stopped policy, choose Resume first. A value that a contract wallet does not store cannot change in place: create a new policy with it.\"},\n    {\"code\": \"revision_changed\", \"for\": \"owner\", \"title\": \"The values changed in the meantime\", \"cause\": \"The change names another revision of the policy's values than the server holds now: a newer one, or none that is valid.\", \"next\": \"Reload the page, read the current values, and make the change again.\"},\n    {\"code\": \"update_unrecorded\", \"for\": \"owner\", \"title\": \"The change is on the ledger and not yet saved\", \"cause\": \"The network confirmed the change. The server did not save the new value in its record.\", \"next\": \"Enter the value of that change again, as it was signed. Allowit finds the confirmed change and saves it without a second signature.\"},\n    {\"code\": \"nothing_to_return\", \"for\": \"owner\", \"title\": \"Nothing of this asset can return\", \"cause\": \"The wallet holds nothing of the chosen asset above what it must keep, so none of it can move back to the owner.\", \"next\": \"Check the asset that the return names. The wallet's balance shows whether another asset, such as its fee balance, can still return.\"},\n    {\"code\": \"wallet_closed\", \"for\": \"owner\", \"title\": \"This wallet is closed\", \"cause\": \"The wallet account no longer exists on the network. History shows whether its funds returned to the owner.\", \"next\": \"Open History to see how the wallet closed. Start a new policy for a new wallet.\"},\n    {\"code\": \"policy_build_identity_changed\", \"for\": \"owner\", \"title\": \"The policy no longer matches its approval\", \"cause\": \"The server part of this policy differs from what the owner approved: its stored source or its language changed, or this release no longer builds the approved source.\", \"next\": \"Start a new policy from the same request and check its source before you sign, or ask the operator of this server what changed.\", \"agent\": \"Tell the owner that the policy no longer matches its approval. Do not send this request again. Ask the owner before a new request for the same purchase.\", \"retry\": \"none\"},\n    {\"code\": \"policy_unknown\", \"for\": \"agent\", \"title\": \"The server has no policy with this id\", \"cause\": \"The policy id in the command is not a policy of this server. The line was cut, or it belongs to another server.\", \"next\": \"Copy the agent prompt from Agent access on the policy page and give your agent the whole line.\", \"agent\": \"Ask the owner for the agent prompt from the Allowit app, and check ALLOWIT_URL.\"},\n    {\"code\": \"not_policy_agent\", \"for\": \"agent\", \"title\": \"This key is not the agent key of the policy\", \"cause\": \"The request is signed with another key than the agent public key that the owner gave the policy.\", \"next\": \"Check the agent public key under Funding on the policy page. The agent must sign with that key, or the agent's key needs a new policy.\", \"agent\": \"Sign with the key whose public key you gave the owner: allowit keys use NAME. Or give the owner this public key for a new policy.\"},\n    {\"code\": \"policy_denied\", \"for\": \"agent\", \"title\": \"The policy denied the payment\", \"cause\": \"The request breaks a rule of the policy, such as an amount limit, a recipient list or a time limit. The details name the rule when the wallet reports one.\", \"next\": \"Open History on the policy page to see why it was denied. Change a value in the policy code only when the details name a rule whose value should change, such as a limit or the recipient list. The agent reads the earlier request first and does not pay twice for one purchase.\", \"agent\": \"Read the earlier request with allowit status ID first. Read the limits with allowit POLICY help. Tell the owner what was denied, with the rule when the details name one, and wait until the owner has acted. If it is pending, wait. If it is the same purchase and it settled, do not pay for it again. Send a new request with a new request ID only once the earlier one is denied, expired or failed, or when it was another purchase.\", \"retry\": \"final\"},\n    {\"code\": \"policy_evaluation_failed\", \"for\": \"agent\", \"title\": \"The policy failed on this request\", \"cause\": \"The policy stopped with an error of its own while it evaluated this request, such as an overflow or a broken state, and no rule denied it.\", \"next\": \"Open History to see the error that the details name. A policy that fails on a request needs a new policy. The agent does not send it again without you.\", \"agent\": \"Tell the owner that the policy failed on this request, with the error that the details name. Do not send this request again. Ask the owner before a new request for the same purchase.\", \"retry\": \"none\"},\n    {\"code\": \"server_policy_denied\", \"for\": \"agent\", \"title\": \"The policy's server part refused the request\", \"cause\": \"The part of the policy that the server runs stopped at one of its limits or could not complete a required lookup.\", \"next\": \"Open History on the policy page: it shows the request and the reason. The agent reads the earlier request first and does not pay twice for one purchase.\", \"agent\": \"Read the earlier request with allowit status ID first. Tell the owner, who sees the request and its reason in History, and wait until the owner has acted. If it is pending, wait. If it is the same purchase and it settled, do not pay for it again. Send a new request with a new request ID only once the earlier one is denied, expired or failed, or when it was another purchase.\", \"retry\": \"final\"},\n    {\"code\": \"decision_denied\", \"for\": \"agent\", \"title\": \"The policy's question denied the request\", \"cause\": \"The policy asks a question about each request, and the answer for this one was below the owner's threshold.\", \"next\": \"Open History on the policy page to read the reason. If the answer was wrong, change the thresholds in the policy code when they are values of the policy, or start a new policy. The agent does not send it again without you.\", \"agent\": \"Tell the owner. The owner reads the reason in History and can change the policy. Do not send this request again. Ask the owner before a new request for the same purchase.\", \"retry\": \"none\"},\n    {\"code\": \"operation_changed\", \"for\": \"agent\", \"title\": \"The operation changed while it was read\", \"cause\": \"Another request changed this operation at the same moment.\", \"next\": \"No action is needed. The agent sends the same request again.\", \"agent\": \"Send the same request again unchanged, with the same request ID or payment authorization: the server never does one request twice.\", \"retry\": \"same\"},\n    {\"code\": \"operation_unresolved\", \"for\": \"agent\", \"title\": \"The server could not read the operation now\", \"cause\": \"A read of the operation failed on the server, and the read changed nothing.\", \"next\": \"No action is needed. The agent sends the same request again.\", \"agent\": \"Send the same request again unchanged, with the same request ID or payment authorization: the server never does one request twice.\", \"retry\": \"same\"},\n    {\"code\": \"operation_refused\", \"for\": \"agent\", \"title\": \"The server refused the operation\", \"cause\": \"The server did not complete this operation, and the details state the reason. An operation that was submitted before the refusal can still take effect.\", \"next\": \"Open History to see the refused request. The details name what to correct. The agent reads the earlier request first and does not pay twice for one purchase.\", \"agent\": \"Read the earlier request with allowit status ID first. Correct what the details name. If it is pending, wait. If it is the same purchase and it settled, do not pay for it again. Send a new request with a new request ID only once the earlier one is denied, expired or failed, or when it was another purchase.\", \"retry\": \"final\"},\n    {\"code\": \"request_id_binds_other_input\", \"for\": \"agent\", \"title\": \"This request ID belongs to another request\", \"cause\": \"The request ID was used before with a different amount, recipient or operation.\", \"next\": \"No action is needed. The agent reads the earlier request first and does not pay twice for one purchase.\", \"agent\": \"Read the earlier request with allowit status ID first. If it is pending, wait. If it is the same purchase and it settled, do not pay for it again. Send a new request with a new request ID only once the earlier one is denied, expired or failed, or when it was another purchase.\", \"retry\": \"final\"},\n    {\"code\": \"paid_service_mismatch\", \"for\": \"agent\", \"title\": \"The payment and the service call differ\", \"cause\": \"The service context of this request names another recipient, asset or amount than its operation, or does not describe its operation.\", \"next\": \"No action is needed.\", \"agent\": \"Read the details, and build the operation and its service context from the same terms of the seller.\"},\n    {\"code\": \"challenge_already_paid\", \"for\": \"agent\", \"title\": \"Another request holds this service call\", \"cause\": \"Another request of this policy holds the same call of the seller while it is prepared, pending or done.\", \"next\": \"Open History to see how the other request ended. The agent reads the earlier request first and does not pay twice for one purchase.\", \"agent\": \"Read the earlier request with allowit status ID first. The details name the request that holds the call. If it is pending, wait. If it is the same purchase and it settled, do not pay for it again. Send a new request with a new request ID only once the earlier one is denied, expired or failed, or when it was another purchase.\", \"retry\": \"final\"},\n    {\"code\": \"wallet_paused\", \"for\": \"agent\", \"title\": \"The owner stopped this policy\", \"cause\": \"The wallet is paused, so the agent cannot pay from it.\", \"next\": \"Open the policy in the Allowit app and choose Resume under Stop and return funds. The agent sends the same request again once you have acted on it.\", \"agent\": \"Stop using the wallet, and tell the owner that the policy is stopped. Wait until the owner has acted on it. Then send the same request again unchanged, with the same request ID.\", \"retry\": \"owner\"},\n    {\"code\": \"insufficient_funds\", \"for\": \"agent\", \"title\": \"The wallet holds too little\", \"cause\": \"The wallet does not hold what the operation needs, such as the payment amount and its network fee, or the vault shares of a redemption.\", \"next\": \"Check what the operation needs in the details, and send the wallet that asset. The policy page shows the wallet's address under Funding. The agent sends the same request again once you have acted on it.\", \"agent\": \"Tell the owner what the wallet lacks, as the details say. Wait until the owner has acted on it. Then send the same request again unchanged, with the same request ID.\", \"retry\": \"owner\"},\n    {\"code\": \"stale_request\", \"for\": \"agent\", \"title\": \"The request is out of date\", \"cause\": \"The wallet moved past the state that this request or step was prepared for: another payment or owner step changed it first.\", \"next\": \"Reload the policy page and prepare the step again. The agent reads the earlier request first and does not pay twice for one purchase.\", \"agent\": \"Read the earlier request with allowit status ID first. If it is pending, wait. If it is the same purchase and it settled, do not pay for it again. Send a new request with a new request ID only once the earlier one is denied, expired or failed, or when it was another purchase.\", \"retry\": \"final\"},\n    {\"code\": \"wallet_rejected\", \"for\": \"agent\", \"title\": \"A contract refused the operation\", \"cause\": \"The wallet, its asset or a vault refused the operation in simulation. The details name the contract error when it is known.\", \"next\": \"Open the policy page and check that the wallet is active. The details name the contract error.\", \"agent\": \"Read the contract error in the details. Run allowit POLICY help to check the wallet's state, and tell the owner if the wallet is stopped or changed.\"},\n    {\"code\": \"seller_failed\", \"for\": \"agent\", \"title\": \"The seller did not complete the call\", \"cause\": \"The seller refused, failed, or sent no usable terms, before any payment of this call.\", \"next\": \"No action is needed. The agent sends the same request again.\", \"agent\": \"Wait a moment, or choose another seller. Send the same request again unchanged, with the same request ID or payment authorization: the server never does one request twice.\", \"retry\": \"same\"},\n    {\"code\": \"seller_failed_after_payment\", \"for\": \"agent\", \"title\": \"The seller failed after the payment\", \"cause\": \"The seller refused or failed the call that carried the payment of this request.\", \"next\": \"Open History to see this call. The agent reads the earlier request first and does not pay twice for one purchase.\", \"agent\": \"Read the earlier request with allowit status ID first. Ask the seller for the result of this call. If it is pending, wait. If it is the same purchase and it settled, do not pay for it again. Send a new request with a new request ID only once the earlier one is denied, expired or failed, or when it was another purchase.\", \"retry\": \"final\"},\n    {\"code\": \"policy_not_active\", \"for\": \"agent\", \"title\": \"The policy is not active\", \"cause\": \"The owner stopped or changed the policy.\", \"next\": \"Open the policy in the Allowit app. Choose Resume under Stop and return funds, or finish Review and sign. The agent sends the same request again once you have acted on it.\", \"agent\": \"Run allowit POLICY help to read its state, and ask the owner. Wait until the owner has acted on it. Then send the same request again unchanged, with the same request ID.\", \"retry\": \"owner\"},\n    {\"code\": \"wallet_unverified\", \"for\": \"agent\", \"title\": \"The ledger does not show this wallet for the policy\", \"cause\": \"The wallet that this device imported does not hold the policy on the network now.\", \"next\": \"Check on the policy page that the wallet is active on this network, and tell the agent if it changed. The agent sends the same request again.\", \"agent\": \"Ask the owner whether the wallet still exists, and import it with allowit wallet import --policy=POLICY. Send the same request again unchanged, with the same request ID or payment authorization: the server never does one request twice.\", \"retry\": \"same\"},\n    {\"code\": \"wallet_differs\", \"for\": \"agent\", \"title\": \"The policy now pays from another wallet\", \"cause\": \"The owner deployed the policy to another wallet than the one that this device imported.\", \"next\": \"No action is needed. The agent imports the current wallet of the policy. The agent sends the same request again.\", \"agent\": \"Run allowit wallet import --policy=POLICY, then allowit wallet use with the new wallet. Send the same request again unchanged, with the same request ID or payment authorization: the server never does one request twice.\", \"retry\": \"same\"},\n    {\"code\": \"server_key_differs\", \"for\": \"agent\", \"title\": \"The server key differs from the trusted one\", \"cause\": \"The server names another key for this policy than the key that this device pinned.\", \"next\": \"Compare the key with Server public key under Agent access in the Allowit app. If they differ, stop. The agent does not send it again without you.\", \"agent\": \"Stop. Ask the owner which server key the app shows under Agent access. Do not send this request again. Ask the owner before a new request for the same purchase.\", \"retry\": \"none\"},\n    {\"code\": \"request_proof_refused\", \"for\": \"agent\", \"title\": \"The server refused the request's signature\", \"cause\": \"The request carries a signature of the agent key that the server could not verify. A wrong device clock is the usual cause.\", \"next\": \"No action is needed. The agent sends the same request again.\", \"agent\": \"Set this device's clock. Send the same request again unchanged, with the same request ID or payment authorization: the server never does one request twice.\", \"retry\": \"same\"},\n    {\"code\": \"request_proof_missing\", \"for\": \"agent\", \"title\": \"The request carries no agent proof\", \"cause\": \"The server takes agent requests only with the proof that the allowit CLI of this server adds, and this request had none.\", \"next\": \"Give the agent the agent prompt from Agent access again: its install line installs the CLI that this server serves. The agent sends the same request again.\", \"agent\": \"Install the CLI that this server serves with the install line of its app. Send the same request again unchanged, with the same request ID or payment authorization: the server never does one request twice.\", \"retry\": \"same\"},\n    {\"code\": \"credits_exhausted\", \"for\": \"owner\", \"title\": \"The credits do not cover a request\", \"cause\": \"Allowit charges the policy's owner credits for each evaluation of a request and each explanation of a score, and the owner's available credits are less than this one costs.\", \"next\": \"Open Credits in the header and get credits. A request that waits in Approval can still be answered without an explanation.\", \"agent\": \"Tell the owner to get credits from Allowit: the app shows the balance and how. The agent needs no credits of its own. Wait until the owner has acted on it. Then send the same request again unchanged, with the same request ID.\", \"retry\": \"owner\"},\n    {\"code\": \"credits_insufficient\", \"for\": \"owner\", \"title\": \"The credits do not cover a lookup of the policy\", \"cause\": \"The policy looks something up or asks a model before it decides. The owner's credits cover the request and not that call, so the request was denied.\", \"next\": \"Open Credits in the header and get credits.\", \"agent\": \"Read the earlier request with allowit status ID first. Tell the owner to get credits from Allowit, wait until the owner has, and do not work around the denial. If it is pending, wait. If it is the same purchase and it settled, do not pay for it again. Send a new request with a new request ID only once the earlier one is denied, expired or failed, or when it was another purchase.\", \"retry\": \"final\"},\n    {\"code\": \"allowance_exhausted\", \"for\": \"owner\", \"title\": \"Today's analysis allowance is used up\", \"cause\": \"The owner limits the calls of a policy each day that count against its allowance under the server's price list, and what they cost. This request or an explanation needed one more.\", \"next\": \"Open Usage on the policy page and raise the allowance, or wait until 00:00 UTC. A request that waits in Approval can still be answered.\", \"agent\": \"Read the earlier request with allowit status ID first. Tell the owner to raise the analysis allowance of the policy in the app, or wait until 00:00 UTC. If it is pending, wait. If it is the same purchase and it settled, do not pay for it again. Send a new request with a new request ID only once the earlier one is denied, expired or failed, or when it was another purchase.\", \"retry\": \"final\"},\n    {\"code\": \"credit_limit_reached\", \"for\": \"owner\", \"title\": \"The request would pass the policy's credit limit\", \"cause\": \"The owner limits the credits that one request of this policy can use, and a call of this request or of its explanation could pass that limit, so it was not made.\", \"next\": \"Raise or remove the credit limit of the policy if the request is worth more. A request that waits in Approval can still be answered without an explanation.\", \"agent\": \"Read the earlier request with allowit status ID first. Tell the owner that the request would pass the credit limit of the policy, and wait until the owner has acted. If it is pending, wait. If it is the same purchase and it settled, do not pay for it again. Send a new request with a new request ID only once the earlier one is denied, expired or failed, or when it was another purchase.\", \"retry\": \"final\"},\n    {\"code\": \"owner_key_unavailable\", \"for\": \"operator\", \"title\": \"This server cannot keep an owner's model key\", \"cause\": \"The server has no secret to seal an owner's Gemini API key, so its own provider serves every call.\", \"next\": \"No action is needed: Allowit's provider serves the policies. To use your own key, ask the operator of this server to configure its engine seed.\"},\n    {\"code\": \"owner_key_invalid\", \"for\": \"owner\", \"title\": \"The Gemini API key is not in a valid form\", \"cause\": \"Allowit takes a Gemini API key as one run of printable characters, without spaces, of a bounded length.\", \"next\": \"Copy the whole Gemini API key from the provider's console, without spaces, and enter it again.\"},\n    {\"code\": \"owner_key_unreadable\", \"for\": \"agent\", \"title\": \"The owner's model key cannot be read\", \"cause\": \"The Gemini API key that the owner stored cannot be opened on this server, so the calls that need it were not made.\", \"next\": \"Enter your Gemini API key again, or remove it to let Allowit's provider serve the policy. The agent sends the same request again once you have acted on it.\", \"agent\": \"Tell the owner that the stored Gemini API key cannot be read on this server. Wait until the owner has acted on it. Then send the same request again unchanged, with the same request ID.\", \"retry\": \"owner\"},\n    {\"code\": \"credits_unavailable\", \"for\": \"agent\", \"title\": \"Allowit released no decision\", \"cause\": \"The server could not reserve or save the cost of this request, so it decided nothing.\", \"next\": \"No action is needed. The agent sends the same request again.\", \"agent\": \"Send the same request again unchanged, with the same request ID or payment authorization: the server never does one request twice.\", \"retry\": \"same\"},\n    {\"code\": \"evaluation_conflict\", \"for\": \"agent\", \"title\": \"This request ID already has a decision\", \"cause\": \"An earlier evaluation of the same request ID decided first. The ledger keeps that decision.\", \"next\": \"No action is needed. History shows how Allowit decided the request. The agent reads the earlier request first and does not pay twice for one purchase.\", \"agent\": \"Read the earlier request with allowit status ID first. If it is pending, wait. If it is the same purchase and it settled, do not pay for it again. Send a new request with a new request ID only once the earlier one is denied, expired or failed, or when it was another purchase.\", \"retry\": \"final\"},\n    {\"code\": \"evaluation_running\", \"for\": \"agent\", \"title\": \"Allowit is evaluating this request now\", \"cause\": \"An earlier call with the same request ID has not ended.\", \"next\": \"No action is needed. Allowit is deciding the request now. The agent reads the earlier request first and does not pay twice for one purchase.\", \"agent\": \"Read the earlier request with allowit status ID first. If it is pending, wait. If it is the same purchase and it settled, do not pay for it again. Send a new request with a new request ID only once the earlier one is denied, expired or failed, or when it was another purchase.\", \"retry\": \"final\"},\n    {\"code\": \"call_unpriced\", \"for\": \"operator\", \"title\": \"The policy made a call without a price\", \"cause\": \"The policy asked for a lookup, or a payment needs a fee in an asset, that the price list of this server does not price.\", \"next\": \"Ask the operator to add the price that the details name. For an unpriced lookup only, a draft can drop it in the conversation, and a signed policy needs a new policy without it.\"},\n    {\"code\": \"charge_unknown\", \"for\": \"owner\", \"title\": \"No charge was found for these IDs\", \"cause\": \"Allowit found no charge for this policy and request: a request costs credits when it is evaluated, and the command may name the wrong policy or request.\", \"next\": \"Check the policy and the request in History.\", \"agent\": \"Check that the command names the right policy and request.\"},\n    {\"code\": \"grant_id_used\", \"for\": \"operator\", \"title\": \"This grant id was used before\", \"cause\": \"The grant id already granted credits to this owner.\", \"next\": \"No action is needed: the credits of this grant were granted before. The operator names a new grant for another one.\"},\n    {\"code\": \"operator_credential_required\", \"for\": \"operator\", \"title\": \"Only the operator grants credits\", \"cause\": \"The request carries no operator credential, which a grant of credits needs. An owner session does not grant credits.\", \"next\": \"Ask the operator of this server for the credits: only the operator's credential grants them.\"},\n    {\"code\": \"owner_review_pending\", \"for\": \"agent\", \"title\": \"The request waits for its owner\", \"cause\": \"The policy holds this request until the owner allows or denies it.\", \"next\": \"Open Approval on the policy page and choose Allow or Deny. The agent sends the same request again once you have acted on it.\", \"agent\": \"Ask the owner to answer the request in the Allowit app. Wait until the owner has acted on it. Then send the same request again unchanged, with the same request ID.\", \"retry\": \"owner\"},\n    {\"code\": \"owner_review_allowed\", \"for\": \"agent\", \"title\": \"The request was allowed after review\", \"cause\": \"The owner, new evidence or the policy after a new fetch allowed this request. It has no payment yet.\", \"next\": \"No action is needed. The agent sends the same request again.\", \"agent\": \"Act before the time in the details. Send the same request again unchanged, with the same request ID or payment authorization: the server never does one request twice.\", \"retry\": \"same\"},\n    {\"code\": \"owner_review_denied\", \"for\": \"agent\", \"title\": \"The request was denied\", \"cause\": \"The owner denied this request, or the policy denied it after new evidence.\", \"next\": \"No action is needed. The agent does not send it again without you.\", \"agent\": \"Do not send this request again. Ask the owner before a new request for the same purchase.\", \"retry\": \"none\"},\n    {\"code\": \"owner_review_expired\", \"for\": \"agent\", \"title\": \"The request expired\", \"cause\": \"The owner did not answer in time, or an allowed request was not sent in time. It counts as denied.\", \"next\": \"Answer the new request in Approval when the agent sends it. The agent reads the earlier request first and does not pay twice for one purchase.\", \"agent\": \"Read the earlier request with allowit status ID first. Tell the owner that a new request will wait in Approval. If it is pending, wait. If it is the same purchase and it settled, do not pay for it again. Send a new request with a new request ID only once the earlier one is denied, expired or failed, or when it was another purchase.\", \"retry\": \"final\"},\n    {\"code\": \"owner_review_request_changed\", \"for\": \"agent\", \"title\": \"This request ID was reviewed with other values\", \"cause\": \"The request ID belongs to a request that went to the owner's review with a different amount, recipient or text. That request can still wait, or it has an answer or an operation.\", \"next\": \"No action is needed. The agent reads the earlier request first and does not pay twice for one purchase.\", \"agent\": \"Read the earlier request with allowit status ID first. If it is pending, wait. If it is the same purchase and it settled, do not pay for it again. Send a new request with a new request ID only once the earlier one is denied, expired or failed, or when it was another purchase.\", \"retry\": \"final\"},\n    {\"code\": \"owner_review_spent\", \"for\": \"agent\", \"title\": \"This approval is already used\", \"cause\": \"The owner's approval of this request was already used for an operation. Its status shows how that operation ended.\", \"next\": \"Open History to see the operation of the allowed request. The agent reads the earlier request first and does not pay twice for one purchase.\", \"agent\": \"Read the earlier request with allowit status ID first. If it is pending, wait. If it is the same purchase and it settled, do not pay for it again. Send a new request with a new request ID only once the earlier one is denied, expired or failed, or when it was another purchase.\", \"retry\": \"final\"},\n    {\"code\": \"owner_review_second_question\", \"for\": \"agent\", \"title\": \"The request needs the owner again\", \"cause\": \"The owner allowed the request at one point of the policy, and it stopped at another point that also needs the owner. One request carries one answer, so the request is denied.\", \"next\": \"Change the policy so that it asks you once for this kind of request: revise a draft in the conversation, or start a new policy. The agent does not send it again without you.\", \"agent\": \"Tell the owner that the policy asks twice for this request: a new request stops at the same point. Do not send this request again. Ask the owner before a new request for the same purchase.\", \"retry\": \"none\"},\n    {\"code\": \"owner_review_unknown\", \"for\": \"owner\", \"title\": \"This request is not in the owner's list\", \"cause\": \"No waiting request with this id belongs to the signed-in account.\", \"next\": \"Open the policy and choose a request from Approval.\"},\n    {\"code\": \"owner_review_snapshot_stale\", \"for\": \"owner\", \"title\": \"The evidence was fetched again\", \"cause\": \"The request shows newer evidence than the page that was answered.\", \"next\": \"Read the request again in Approval and answer what it shows now.\"},\n    {\"code\": \"owner_review_snapshot_mismatch\", \"for\": \"owner\", \"title\": \"The answer does not match the request\", \"cause\": \"The answer names evidence that this waiting request never had.\", \"next\": \"Open the request again in Approval and answer what it shows.\"},\n    {\"code\": \"owner_review_answered\", \"for\": \"owner\", \"title\": \"This request is already decided\", \"cause\": \"The owner, the policy's question or the time limit decided the request before this answer.\", \"next\": \"Read the request again in Approval to see how it ended.\"},\n    {\"code\": \"owner_review_signature_invalid\", \"for\": \"owner\", \"title\": \"The answer is not signed by the owner account\", \"cause\": \"The wallet signed the answer to this waiting request with another account, or signed another message.\", \"next\": \"Select the policy's owner account in your wallet and choose Allow or Deny again.\"},\n    {\"code\": \"owner_review_flag_snapshot_mismatch\", \"for\": \"owner\", \"title\": \"The flag names another view of this decision\", \"cause\": \"Deny next time named a view of the past decision that the server does not hold.\", \"next\": \"Open the decision in Approval again, and choose Deny next time on what it shows.\"},\n    {\"code\": \"owner_review_flag_signature_invalid\", \"for\": \"owner\", \"title\": \"The flag is not signed for this decision\", \"cause\": \"The signature of Deny next time does not belong to the owner account and this past decision.\", \"next\": \"Select the policy's owner account in your wallet, then choose Deny next time on the decision in Approval.\"},\n    {\"code\": \"owner_review_not_owner\", \"for\": \"owner\", \"title\": \"These requests belong to another owner\", \"cause\": \"The signed-in account does not own this policy.\", \"next\": \"Sign in with the owner account of the policy.\"},\n    {\"code\": \"owner_review_refetch_unavailable\", \"for\": \"owner\", \"title\": \"The evidence cannot be fetched again\", \"cause\": \"This server cannot repeat the lookups of the request.\", \"next\": \"Answer the request as it is, or let it expire.\"},\n    {\"code\": \"owner_review_refetch_limit\", \"for\": \"owner\", \"title\": \"The evidence was fetched as often as allowed\", \"cause\": \"A request can have its evidence fetched again a limited number of times, and this one reached that limit.\", \"next\": \"Answer the request in Approval as it is.\"},\n    {\"code\": \"owner_review_refetch_cooldown\", \"for\": \"owner\", \"title\": \"Fetch the evidence in a few seconds\", \"cause\": \"The evidence of a request is fetched at most once in a few seconds.\", \"next\": \"Wait a few seconds, then choose Fetch evidence again.\"},\n    {\"code\": \"owner_review_changed\", \"for\": \"owner\", \"title\": \"The request changed during the answer\", \"cause\": \"New evidence, an answer or a reopening changed the request at the same moment.\", \"next\": \"Read the request again in Approval.\"},\n    {\"code\": \"owner_review_not_reopenable\", \"for\": \"owner\", \"title\": \"This decision cannot be reopened\", \"cause\": \"Reopening applies only to a denied or expired request without a payment, and flagging only to a decision that the policy's question scored.\", \"next\": \"Open the decision in Approval. Reopen applies to a denied or expired request without an operation that the owner or the policy's question decided; Deny next time applies to a decision that the question scored.\"},\n    {\"code\": \"owner_review_policy_changed\", \"for\": \"owner\", \"title\": \"The policy changed since this decision\", \"cause\": \"The request was decided under an earlier version of the policy.\", \"next\": \"Ask the agent for a new request under the current policy: the agent reads the earlier request first.\", \"agent\": \"Read the earlier request with allowit status ID first. The current policy decides a new request. If it is pending, wait. If it is the same purchase and it settled, do not pay for it again. Send a new request with a new request ID only once the earlier one is denied, expired or failed, or when it was another purchase.\", \"retry\": \"final\"},\n    {\"code\": \"owner_review_answer_superseded\", \"for\": \"owner\", \"title\": \"A later answer stands\", \"cause\": \"The owner answered this request again after the decision that was opened.\", \"next\": \"Open the latest decision of the request to flag it.\"},\n    {\"code\": \"owner_review_explanation_unavailable\", \"for\": \"owner\", \"title\": \"No explanation is available now\", \"cause\": \"Allowit could not write the short explanation of the score.\", \"next\": \"Decide from the evidence on the page: it is everything that the decision saw.\"},\n    {\"code\": \"owner_review_invalid\", \"for\": \"agent\", \"title\": \"The request cannot be held for the owner\", \"cause\": \"A field of the request, or of what the server holds with it, is malformed or too long for the owner's review. The details name it.\", \"next\": \"No action is needed.\", \"agent\": \"Correct the field that the details name, and send the corrected request.\"},\n    {\"code\": \"owner_review_queue_full\", \"for\": \"agent\", \"title\": \"Too many requests wait for the owner\", \"cause\": \"The policy holds a limited number of requests for the owner at a time, and that number is reached.\", \"next\": \"Open Approval on the policy page and answer some of the waiting requests. The agent sends the same request again once you have acted on it.\", \"agent\": \"Ask the owner to answer the requests that wait in Approval. Wait until the owner has acted on it. Then send the same request again unchanged, with the same request ID.\", \"retry\": \"owner\"},\n    {\"code\": \"owner_review_refetch_undecided\", \"for\": \"owner\", \"title\": \"The request cannot be evaluated again\", \"cause\": \"The server cannot run this request once more. The details state why.\", \"next\": \"Answer the request in Approval as it is.\"},\n    {\"code\": \"decision_review_needed\", \"for\": \"agent\", \"title\": \"The owner must decide this request\", \"cause\": \"The answer to the policy's question fell between the owner's thresholds, so the owner decides.\", \"next\": \"Open Approval on the policy page and answer the request. The agent sends the same request again once you have acted on it.\", \"agent\": \"Ask the owner to answer the request in the Allowit app. Wait until the owner has acted on it. Then send the same request again unchanged, with the same request ID.\", \"retry\": \"owner\"},\n    {\"code\": \"decision_unavailable\", \"for\": \"agent\", \"title\": \"The policy's question got no answer\", \"cause\": \"The model that answers the policy's question did not answer in time, so the request was not allowed.\", \"next\": \"No action is needed. The agent sends the same request again.\", \"agent\": \"Wait a moment. Send the same request again unchanged, with the same request ID or payment authorization: the server never does one request twice.\", \"retry\": \"same\"},\n    {\"code\": \"decision_provider_invalid\", \"for\": \"operator\", \"title\": \"The decision provider gave no usable answer\", \"cause\": \"The provider that answers the policy's question refused it, or answered in a form that the server cannot read.\", \"next\": \"Give the operator of this server the code decision_provider_invalid: the provider's settings need a check.\", \"agent\": \"Tell the owner that the decision provider of this server needs its operator. Wait until the owner has acted on it. Then send the same request again unchanged, with the same request ID.\", \"retry\": \"owner\"},\n    {\"code\": \"decision_unconfigured\", \"for\": \"operator\", \"title\": \"This server answers no policy questions\", \"cause\": \"The policy asks a question about each request, and this server has no model for it.\", \"next\": \"Use a server that answers questions, or a policy without the question: revise a draft in the conversation, or start a new policy for a signed one.\"},\n    {\"code\": \"decision_blocked\", \"for\": \"owner\", \"title\": \"The model refused to read the request\", \"cause\": \"The content filter of the model blocked the text of the request or its evidence.\", \"next\": \"Open History to read the request. Allow such requests by a fixed rule, or ask the agent to send plain text.\"},\n    {\"code\": \"decision_evidence_too_large\", \"for\": \"owner\", \"title\": \"The request is too large for the question\", \"cause\": \"The request and what the policy looked up exceed what the model reads at once.\", \"next\": \"Ask the agent to send a shorter request text. To shorten the policy's lookups, revise a draft in the conversation, or start a new policy for a signed one.\"},\n    {\"code\": \"decision_past_answers_unavailable\", \"for\": \"agent\", \"title\": \"The owner's earlier answers could not be read\", \"cause\": \"The policy's question reads the owner's past answers, and the server could not load them.\", \"next\": \"No action is needed. The agent sends the same request again.\", \"agent\": \"Wait a moment. Send the same request again unchanged, with the same request ID or payment authorization: the server never does one request twice.\", \"retry\": \"same\"},\n    {\"code\": \"decision_thresholds_invalid\", \"for\": \"owner\", \"title\": \"The thresholds of the question are invalid\", \"cause\": \"The score below which the policy denies is higher than the score above which it allows, or a threshold is out of range.\", \"next\": \"Set both thresholds from 0 to 10,000, the deny threshold at most the allow one: in the policy code when they are values of the policy, or in a new policy when the source fixes them.\"},\n    {\"code\": \"decision_question_invalid\", \"for\": \"owner\", \"title\": \"The policy's question is invalid\", \"cause\": \"The question is empty, too long or malformed.\", \"next\": \"In a draft, state the question again in the conversation in one or two plain sentences. A signed policy keeps its source: start a new policy.\"},\n    {\"code\": \"fetch_request_refused\", \"for\": \"owner\", \"title\": \"The policy's lookup is not allowed\", \"cause\": \"The lookup is malformed or exceeds a fixed bound of a fetch.\", \"next\": \"Correct the field of the lookup that the details name: in a draft, in the conversation; for a signed policy, in a new policy.\"},\n    {\"code\": \"fetch_address_refused\", \"for\": \"owner\", \"title\": \"The lookup address is not public\", \"cause\": \"The policy reads a URL that does not resolve to public internet addresses only.\", \"next\": \"Use a public https address for the lookup: in a draft, in the conversation; for a signed policy, in a new policy.\"},\n    {\"code\": \"fetch_unauthorized\", \"for\": \"owner\", \"title\": \"The looked-up service refused access\", \"cause\": \"The service that the policy reads answered that the request is not authorized.\", \"next\": \"Check the access to that service. To change the lookup, revise a draft in the conversation, or start a new policy for a signed one.\"},\n    {\"code\": \"fetch_failed\", \"for\": \"agent\", \"title\": \"The policy's lookup failed\", \"cause\": \"The service that the policy reads did not answer in time, or answered with an error status, so the request was not allowed.\", \"next\": \"No action is needed. The agent sends the same request again.\", \"agent\": \"Wait a moment. Send the same request again unchanged, with the same request ID or payment authorization: the server never does one request twice.\", \"retry\": \"same\"},\n    {\"code\": \"fetch_response_unusable\", \"for\": \"agent\", \"title\": \"The policy's lookup got an unusable report\", \"cause\": \"The service that the policy reads answered with a report that the policy cannot use, such as a redirect or a report over 1 MiB.\", \"next\": \"Point the lookup at a usable report: in the conversation for a draft, or in a new policy for a signed one. The agent does not send it again without you.\", \"agent\": \"Tell the owner that the policy's lookup needs a usable report. Do not send this request again. Ask the owner before a new request for the same purchase.\", \"retry\": \"none\"},\n    {\"code\": \"fetch_unconfigured\", \"for\": \"operator\", \"title\": \"This server runs no lookups\", \"cause\": \"The policy reads a service, and this server has no fetcher for it.\", \"next\": \"Use a server that runs lookups, or a policy without the lookup: revise a draft in the conversation, or start a new policy for a signed one.\"},\n    {\"code\": \"fetch_signature_invalid\", \"for\": \"owner\", \"title\": \"The lookup's signature is not valid\", \"cause\": \"The policy expects a signed answer from the service, and the answer carries no signature of the expected key.\", \"next\": \"Check the service's signing key. To change the key or the lookup, revise a draft in the conversation, or start a new policy for a signed one.\"},\n    {\"code\": \"fetch_tls_key_refused\", \"for\": \"owner\", \"title\": \"The service's certificate key changed\", \"cause\": \"The policy pins the key of the service that it reads, and the service presents another key.\", \"next\": \"Confirm the new key with the service. Then state it in a draft's conversation, or start a new policy for a signed one.\"},\n    {\"code\": \"internet_search_unconfigured\", \"for\": \"operator\", \"title\": \"This server runs no web search\", \"cause\": \"The policy searches the web, and this server has no search provider.\", \"next\": \"Use a server with search, or a policy without the search: revise a draft in the conversation, or start a new policy for a signed one.\"},\n    {\"code\": \"internet_search_failed\", \"for\": \"agent\", \"title\": \"The policy's web search failed\", \"cause\": \"The search did not answer in time, so the request was not allowed.\", \"next\": \"No action is needed. The agent sends the same request again.\", \"agent\": \"Wait a moment. Send the same request again unchanged, with the same request ID or payment authorization: the server never does one request twice.\", \"retry\": \"same\"},\n    {\"code\": \"internet_search_provider_invalid\", \"for\": \"operator\", \"title\": \"The search provider gave no usable answer\", \"cause\": \"The provider of the policy's web search refused the search, or answered in a form that the server cannot read.\", \"next\": \"Give the operator of this server the code internet_search_provider_invalid: the provider's settings need a check.\", \"agent\": \"Tell the owner that the search provider of this server needs its operator. Wait until the owner has acted on it. Then send the same request again unchanged, with the same request ID.\", \"retry\": \"owner\"},\n    {\"code\": \"internet_search_no_results\", \"for\": \"agent\", \"title\": \"The policy's web search found nothing\", \"cause\": \"The search ran and found no source for this request, so the policy did not allow it.\", \"next\": \"Open History to see the request. A recipient or a service that the web does not know may need a fixed rule in a new policy. The agent does not send it again without you.\", \"agent\": \"Tell the owner. A recipient or a service that the web does not know may need a fixed rule. Do not send this request again. Ask the owner before a new request for the same purchase.\", \"retry\": \"none\"},\n    {\"code\": \"internet_search_query_invalid\", \"for\": \"owner\", \"title\": \"The policy's search query is invalid\", \"cause\": \"The query that the policy builds is empty, too long or malformed.\", \"next\": \"In a draft, state again in the conversation what the policy searches for. A signed policy keeps its source: start a new policy.\"},\n    {\"code\": \"request_screening_malformed\", \"for\": \"owner\", \"title\": \"The policy's request check is malformed\", \"cause\": \"The custom code of the policy hands the server data in a form that it does not read.\", \"next\": \"In a draft, revise the policy in the conversation so that it builds its check again. A signed policy keeps its source: start a new policy.\"},\n    {\"code\": \"price_denied\", \"for\": \"agent\", \"title\": \"The price is outside the policy's band\", \"cause\": \"The policy compares the price of this payment with a market or vault price, and the price is outside the band that the policy allows.\", \"next\": \"Open History to see the price that the policy refused. The agent reads the earlier request first and does not pay twice for one purchase.\", \"agent\": \"Read the earlier request with allowit status ID first. Wait until the market price is inside the band, or tell the owner which price the policy refused. If it is pending, wait. If it is the same purchase and it settled, do not pay for it again. Send a new request with a new request ID only once the earlier one is denied, expired or failed, or when it was another purchase.\", \"retry\": \"final\"},\n    {\"code\": \"market_too_thin\", \"for\": \"agent\", \"title\": \"The market is too thin for this amount\", \"cause\": \"The order books cannot fill this amount, or too few trades stand behind the price, so the policy cannot rely on it.\", \"next\": \"No action is needed. The agent sends the same request again.\", \"agent\": \"Wait for more trades. Send the same request again unchanged, with the same request ID or payment authorization: the server never does one request twice.\", \"retry\": \"same\"},\n    {\"code\": \"price_unavailable\", \"for\": \"agent\", \"title\": \"The price could not be read\", \"cause\": \"The server could not read a usable price for the policy's check, so the request was not allowed.\", \"next\": \"No action is needed. The agent sends the same request again.\", \"agent\": \"Wait a moment. Send the same request again unchanged, with the same request ID or payment authorization: the server never does one request twice.\", \"retry\": \"same\"},\n    {\"code\": \"evidence_call_limit\", \"for\": \"owner\", \"title\": \"The policy made too many calls\", \"cause\": \"One evaluation keeps a limited record of the policy's calls, its rules and its lookups, and this policy made more.\", \"next\": \"In a draft, revise the policy in the conversation so that it makes fewer calls for each request. A signed policy keeps its source: start a new policy.\"},\n    {\"code\": \"evidence_snapshot_mismatch\", \"for\": \"operator\", \"title\": \"The stored evidence does not match\", \"cause\": \"A repeated evaluation made other lookups than the stored evidence holds.\", \"next\": \"No action is needed. If it repeats, give the operator of this server the code evidence_snapshot_mismatch.\", \"agent\": \"Read the earlier request with allowit status ID first. Tell the owner the code when it repeats. If it is pending, wait. If it is the same purchase and it settled, do not pay for it again. Send a new request with a new request ID only once the earlier one is denied, expired or failed, or when it was another purchase.\", \"retry\": \"final\"},\n    {\"code\": \"marketplace_search_unavailable\", \"for\": \"agent\", \"title\": \"The catalog did not answer the policy\", \"cause\": \"The policy searches the service catalog, and the catalog did not answer in time.\", \"next\": \"No action is needed. The agent sends the same request again.\", \"agent\": \"Wait a moment. Send the same request again unchanged, with the same request ID or payment authorization: the server never does one request twice.\", \"retry\": \"same\"},\n    {\"code\": \"marketplace_search_unconfigured\", \"for\": \"operator\", \"title\": \"This server has no catalog for the policy\", \"cause\": \"The policy searches the service catalog, and this server serves none.\", \"next\": \"Use a server with a catalog, or a policy without the search: revise a draft in the conversation, or start a new policy for a signed one.\"},\n    {\"code\": \"marketplace_search_no_results\", \"for\": \"agent\", \"title\": \"The catalog has no such service\", \"cause\": \"The policy's own catalog search found no entry for this request on this network.\", \"next\": \"Check what the policy searches the catalog for: correct the query in a draft in the conversation, or in a new policy for a signed one. The agent does not send it again without you.\", \"agent\": \"Tell the owner that the policy's catalog search found nothing for this request. Do not send this request again. Ask the owner before a new request for the same purchase.\", \"retry\": \"none\"},\n    {\"code\": \"marketplace_search_query_invalid\", \"for\": \"owner\", \"title\": \"The policy's catalog query is invalid\", \"cause\": \"The query that the policy builds is empty, too long or malformed.\", \"next\": \"In a draft, state again in the conversation what the policy searches the catalog for. A signed policy keeps its source: start a new policy.\"},\n    {\"code\": \"marketplace_unavailable\", \"for\": \"agent\", \"title\": \"This server has no service catalog\", \"cause\": \"The service catalog is not configured on this server.\", \"next\": \"No action is needed. The agent calls a seller directly with its address.\", \"agent\": \"Call a seller directly with allowit call and its URL, or use a server with a catalog.\"},\n    {\"code\": \"marketplace_cursor_stale\", \"for\": \"agent\", \"title\": \"The search results changed\", \"cause\": \"The catalog or its ranking changed since the first page of results.\", \"next\": \"No action is needed. The agent searches the catalog from its first page.\", \"agent\": \"Search without a cursor.\"},\n    {\"code\": \"marketplace_entry_not_found\", \"for\": \"agent\", \"title\": \"The catalog has no entry with this id\", \"cause\": \"The entry was removed, or the id is cut.\", \"next\": \"No action is needed. The agent searches the catalog for a current entry.\", \"agent\": \"Search with allowit skills search, and use an entry from the results.\"},\n    {\"code\": \"facilitator_rate_limited\", \"for\": \"agent\", \"title\": \"The facilitator is at its request limit\", \"cause\": \"The Allowit facilitator serves a limited number of requests each minute.\", \"next\": \"No action is needed. The agent sends the same request again.\", \"agent\": \"Wait a minute. Send the same request again unchanged, with the same request ID or payment authorization: the server never does one request twice.\", \"retry\": \"same\"},\n    {\"code\": \"facilitator_fee_budget_exhausted\", \"for\": \"operator\", \"title\": \"The facilitator's fee budget is used up\", \"cause\": \"The facilitator covers the network fee of the authorizations that it completes from a budget for each hour, and that budget is spent.\", \"next\": \"No action is needed. The operator can raise the budget.\"},\n    {\"code\": \"authorization_already_settled\", \"for\": \"agent\", \"title\": \"This payment is already settled\", \"cause\": \"The facilitator settled this payment authorization before.\", \"next\": \"No action is needed. The agent does not pay for this purchase again.\", \"agent\": \"Do not pay for this purchase again. Read the earlier request with allowit status ID until it is final, or ask the seller for the result.\", \"retry\": \"settled\"},\n    {\"code\": \"authorization_in_settlement\", \"for\": \"agent\", \"title\": \"This payment is being settled now\", \"cause\": \"Another request settles the same payment authorization at this moment.\", \"next\": \"No action is needed. The agent does not pay for this purchase again.\", \"agent\": \"Do not pay for this purchase again. Read the earlier request with allowit status ID until it is final, or ask the seller for the result.\", \"retry\": \"settled\"},\n    {\"code\": \"facilitator_busy\", \"for\": \"agent\", \"title\": \"The facilitator had no free turn\", \"cause\": \"The facilitator got no turn in time for this authorization.\", \"next\": \"No action is needed. The agent sends the same request again.\", \"agent\": \"Wait a moment. Send the same request again unchanged, with the same request ID or payment authorization: the server never does one request twice.\", \"retry\": \"same\"}\n  ]\n}\n";
export const errorCatalogue = freeze(JSON.parse(errorCatalogueSource));
const errorEntries = new Map(errorCatalogue.entries.map(entry => [entry.code, entry]));
export function errorEntry(code) { return typeof code === 'string' ? errorEntries.get(code) ?? null : null; }
export function errorHelpPath(code) { return typeof code === 'string' && /^[a-z][a-z0-9_]{2,63}$/.test(code) ? errorCatalogue.helpPath + code : errorCatalogue.helpPath.slice(0, -1); }
